//! Actual complete two-phase raw/native Lifeforms ownership and delivery.
use super::*;use std::io;
#[path="../../../../analyze/fixtures/report_configuration.rs"]mod report_config;
fn lifeforms_host()->(crate::runner_host::BuildHost,BuildRequest,PathBuf){let(mut host,mut request,root)=fixture("/obj/unread\n/proc/probe(loc)\n    new /obj/unread(loc, 2)\n");std::fs::write(root.join("tools/ci/lint_scopes.toml"),report_config::with_overlay("")).unwrap();for n in 0..140{std::fs::write(root.join(format!("code/filler_{n:03}.dm")),format!("// genuine uncompiled CODE source {n}\n")).unwrap();}let intent=request.policy_inputs.as_mut().unwrap();intent.analysis_context=Some(AnalysisContext::OriginalAnalyze0290);intent.workspace_auxiliary=vec![crate::policy_request::WorkspaceAuxiliaryQuestion::Lifeforms];run(&mut host,&request);(host,request,root)}
#[test]fn actual_lifeforms_reuses_current_body_then_retracts_null_source_and_scope_revisions(){let(mut host,request,root)=lifeforms_host();let queries=Arc::clone(host.query_db());let first=current(&host,|snapshot|snapshot.with_original_lifeforms_policy_report(|data,_,_|{assert!(data.sites().iter().any(|s|s.rule=="ctor_dead_arg"));assert!(data.allow_used().is_empty());Ok(data.sites().to_vec())}).unwrap());let bodies=queries.db().stats(dm_query::Kind(4)).computed;let policies=queries.db().stats(dm_query::Kind(12)).computed;current(&host,|snapshot|snapshot.with_original_lifeforms_policy_report(|data,_,_|{assert_eq!(data.sites(),first);Ok(())}).unwrap());assert_eq!(queries.db().stats(dm_query::Kind(4)).computed,bodies);assert_eq!(queries.db().stats(dm_query::Kind(12)).computed,policies);std::fs::write(root.join("code/probe.dm"),"/obj/unread\n/proc/probe(loc)\n    new /obj/unread(loc, null)\n").unwrap();run(&mut host,&request);current(&host,|snapshot|snapshot.with_original_lifeforms_policy_report(|data,_,_|{assert!(data.sites().is_empty());Ok(())}).unwrap());std::fs::write(root.join("code/probe.dm"),"/obj/unread\n/proc/probe(loc)\n    new /obj/unread(loc, 2)\n").unwrap();std::fs::write(root.join("tools/ci/lint_scopes.toml"),report_config::with_overlay("[lint.lifeforms]\nexempt_files=[\"code/probe.dm\"]\n")).unwrap();run(&mut host,&request);current(&host,|snapshot|snapshot.with_original_lifeforms_policy_report(|data,_,_|{assert!(data.sites().is_empty());Ok(())}).unwrap());}
#[test]fn actual_lifeforms_foreign_db_wrong_role_and_first_writer_io_deny_then_recover(){let(host,_,root)=lifeforms_host();current(&host,|snapshot|{let workspace=snapshot.native_workspace.as_ref().unwrap();let capture=snapshot.workspace_semantic_inputs(crate::policy_request::WorkspaceAuxiliaryQuestion::Lifeforms).unwrap();let guard=snapshot.workspace_native_read().unwrap();assert!(crate::query_db::QueryDb::default().with_original_workspace_lifeforms_guard_report(workspace,&guard,capture,|_,_,_|Ok(())).is_err());assert!(snapshot.with_original_semantic_policy_report(crate::policy_request::WorkspaceAuxiliaryQuestion::SetterPublishes,|_,_,_|Ok(())).is_err());struct Failed;impl io::Write for Failed{fn write(&mut self,_:&[u8])->io::Result<usize>{Err(io::Error::from_raw_os_error(1450))}fn flush(&mut self)->io::Result<()>{Ok(())}}let names=vec!["lifeforms".into()];let actual=snapshot.write_native_workspace_semantic_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&names,None,128,&snapshot.tree,&mut Failed).unwrap_err();assert_eq!(actual.raw_os_error(),Some(1450));let mut bytes=Vec::new();snapshot.write_native_workspace_semantic_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&names,None,128,&snapshot.tree,&mut bytes).unwrap();let text=std::str::from_utf8(&bytes).unwrap();assert!(text.contains("hard_site")&&text.contains("lifeforms"));assert!(snapshot.write_native_workspace_semantic_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&["lifeforms".into(),"sem/reads".into()],None,128,&snapshot.tree,&mut Vec::new()).is_err());});}
